176	struct CommandOutput {
177	    combined: String,
178	    exit_code: Option<i32>,
179	}
180	
181	fn run_command(program: &str, args: &[String]) -> Result<CommandOutput> {
182	    let output = Command::new(program)
183	        .args(args)
184	        .output()
185	        .map_err(|e| anyhow::anyhow!("failed to execute {}: {}", program, e))?;
186	
187	    let mut combined = String::new();
188	    if !output.stdout.is_empty() {
189	        combined.push_str(&String::from_utf8_lossy(&output.stdout));
190	    }
191	    if !output.stderr.is_empty() {
192	        if !combined.is_empty() {
193	            combined.push('\n');
194	        }
195	        combined.push_str(&String::from_utf8_lossy(&output.stderr));
196	    }
197	    Ok(CommandOutput {
198	        combined,
199	        exit_code: output.status.code(),
200	    })
201	}
202	
203	fn print_output(text: &str) {
204	    let stdout = std::io::stdout();
205	    let mut handle = stdout.lock();
206	    let _ = handle.write_all(text.as_bytes());
207	    if !text.ends_with('\n') {
208	        let _ = handle.write_all(b"\n");
209	    }
210	    let _ = handle.flush();
211	}
212	
213	fn propagate_exit(exit_code: Option<i32>) {
214	    if let Some(code) = exit_code {
215	        if code != 0 {
216	            std::process::exit(code);
217	        }
218	    }
219	}
