34	pub fn uninstall(global: bool) -> Result<()> {
35	    let claude_dir = paths::claude_hooks_dir();
36	    let settings_path = if global {
37	        claude_dir.join("settings.json")
38	    } else {
39	        Path::new(".claude").join("settings.json")
40	    };
41	
42	    if !settings_path.exists() {
43	        println!("No settings file found at {}", settings_path.display());
44	        return Ok(());
45	    }
46	
47	    let settings = std::fs::read_to_string(&settings_path)?;
48	    let mut json: serde_json::Value = serde_json::from_str(&settings)?;
49	
50	    if let Some(hooks) = json.get_mut("hooks") {
51	        if let Some(obj) = hooks.as_object_mut() {
52	            for key in &["PreToolUse", "PostToolUse"] {
53	                if let Some(arr) = obj.get_mut(*key).and_then(|v| v.as_array_mut()) {
54	                    arr.retain(|entry| {
55	                        let is_codeflow = entry
56	                            .get("hooks")
57	                            .and_then(|h| h.as_array())
58	                            .map(|hooks| {
59	                                hooks.iter().any(|h| {
60	                                    h.get("command")
61	                                        .and_then(|c| c.as_str())
62	                                        .map(|c| c.contains("codeflow"))
63	                                        .unwrap_or(false)
64	                                })
65	                            })
66	                            .unwrap_or(false);
67	                        !is_codeflow
68	                    });
69	                    if arr.is_empty() {
70	                        obj.remove(*key);
71	                    }
72	                }
73	            }
74	            if obj.is_empty() {
75	                json.as_object_mut().unwrap().remove("hooks");
76	            }
77	        }
78	    }
79	
80	    let output = serde_json::to_string_pretty(&json)?;
81	    std::fs::write(&settings_path, output)?;
82	    println!("✓ CODEFLOW hooks removed from {}", settings_path.display());
83	
84	    Ok(())
85	}
