93	fn check_rtk_conflict(settings_path: &Path) -> Result<()> {
94	    if !settings_path.exists() {
95	        return Ok(());
96	    }
97	    let content = std::fs::read_to_string(settings_path)?;
98	    if content.contains("rtk") || content.contains("RTK") {
99	        eprintln!("⚠ Warning: Existing RTK hooks detected in {}", settings_path.display());
100	        eprintln!("  CODEFLOW will override RTK hooks. Remove RTK hooks manually if needed.");
101	    }
102	    Ok(())
103	}
104	
105	fn read_or_create_settings(path: &Path) -> Result<String> {
106	    if path.exists() {
107	        Ok(std::fs::read_to_string(path)?)
108	    } else {
109	        Ok("{}".to_string())
110	    }
111	}
