113	fn inject_hooks(settings_json: &str, codeflow_bin: &str) -> Result<String> {
114	    let mut json: serde_json::Value = serde_json::from_str(settings_json)?;
115	
116	    let bin_escaped = codeflow_bin.replace('\\', "\\\\");
117	
118	    let pre_hook = serde_json::json!({
119	        "type": "command",
120	        "command": format!("{} hook pre-tool-use", bin_escaped)
121	    });
122	    let post_hook = serde_json::json!({
123	        "type": "command",
124	        "command": format!("{} hook post-tool-use", bin_escaped)
125	    });
126	
127	    let hooks = serde_json::json!({
128	        "PreToolUse": [
129	            { "matcher": "Bash", "hooks": [pre_hook.clone()] },
130	            { "matcher": "Read", "hooks": [pre_hook.clone()] },
131	            { "matcher": "Grep", "hooks": [pre_hook.clone()] },
132	            { "matcher": "Glob", "hooks": [pre_hook] }
133	        ],
134	        "PostToolUse": [
135	            {
136	                "matcher": "Bash|Read|Grep|Glob",
137	                "hooks": [post_hook]
138	            }
139	        ]
140	    });
141	
142	    if let Some(existing) = json.get_mut("hooks").and_then(|h| h.as_object_mut()) {
143	        existing.insert("PreToolUse".to_string(), hooks["PreToolUse"].clone());
144	        existing.insert("PostToolUse".to_string(), hooks["PostToolUse"].clone());
145	    } else {
146	        json["hooks"] = hooks;
147	    }
148	
149	    Ok(serde_json::to_string_pretty(&json)?)
150	}
151	
152	fn write_settings(path: &Path, content: &str) -> Result<()> {
153	    if let Some(parent) = path.parent() {
154	        std::fs::create_dir_all(parent)?;
155	    }
156	    std::fs::write(path, content)?;
157	    Ok(())
158	}
