114	
115	fn save_token(token: &AuthToken) -> Result<()> {
116	    let path = token_path();
117	    if let Some(parent) = path.parent() {
118	        std::fs::create_dir_all(parent)?;
119	    }
120	    let data = serde_json::to_string_pretty(token)?;
121	    std::fs::write(&path, data)?;
122	    Ok(())
123	}
124	
125	fn token_path() -> PathBuf {
126	    paths::config_dir().join("auth.json")
127	}
128	
129	fn extract_code(request_line: &str) -> Option<String> {
130	    let path = request_line.split_whitespace().nth(1)?;
131	    let query_start = path.find('?')?;
132	    let query = &path[query_start + 1..];
133	    for param in query.split('&') {
134	        if let Some(value) = param.strip_prefix("code=") {
135	            return Some(urlencoding::decode(value).ok()?.to_string());
136	        }
137	    }
138	    None
139	}
140	
141	fn exchange_code(auth_url: &str, code: &str, redirect_uri: &str) -> Result<AuthToken> {
142	    let url = format!("{}/token", auth_url);
143	    let body = serde_json::json!({
144	        "grant_type": "authorization_code",
145	        "code": code,
146	        "redirect_uri": redirect_uri,
147	        "client_id": "codeflow-cli",
148	    });
149	
150	    let mut response = ureq::post(&url)
151	        .header("Content-Type", "application/json")
152	        .send(body.to_string().as_bytes())
153	        .map_err(|e| anyhow::anyhow!("token exchange failed: {}", e))?;
154	
155	    let body_str = response.body_mut().read_to_string()
156	        .map_err(|e| anyhow::anyhow!("read token response: {}", e))?;
157	    let resp: serde_json::Value = serde_json::from_str(&body_str)
158	        .map_err(|e| anyhow::anyhow!("invalid token JSON: {}", e))?;
159	
160	    let access_token = resp["access_token"]
161	        .as_str()
162	        .ok_or_else(|| anyhow::anyhow!("missing access_token"))?
163	        .to_string();
164	
165	    let tenant_id = resp["org_id"]
166	        .as_str()
167	        .or_else(|| resp["tenant_id"].as_str())
168	        .unwrap_or("default")
169	        .to_string();
170	
171	    let email = resp["email"]
172	        .as_str()
173	        .unwrap_or("unknown")
174	        .to_string();
175	
176	    let expires_in = resp["expires_in"].as_i64().unwrap_or(86400);
177	    let expires_at = chrono::Utc::now().timestamp() + expires_in;
178	
179	    Ok(AuthToken {
180	        access_token,
181	        refresh_token: resp["refresh_token"].as_str().map(|s| s.to_string()),
182	        tenant_id,
183	        email,
184	        expires_at,
185	    })
186	}
