258	fn format_number(n: u64) -> String {
259	    if n >= 1_000_000 {
260	        format!("{:.1}M", n as f64 / 1_000_000.0)
261	    } else if n >= 1_000 {
262	        format!("{:.1}K", n as f64 / 1_000.0)
263	    } else {
264	        n.to_string()
265	    }
266	}
267	
268	fn truncate(s: &str, max: usize) -> String {
269	    if s.chars().count() > max {
270	        let truncated: String = s.chars().take(max - 1).collect();
271	        format!("{}…", truncated)
272	    } else {
273	        s.to_string()
274	    }
275	}
