76	pub struct FilterPipeline {
77	    configs: Vec<FilterConfig>,
78	}
79	
80	impl FilterPipeline {
81	    pub fn new() -> Self {
82	        Self::default()
83	    }
84	
85	    pub fn load_from_dir(dir: &Path) -> Result<Self> {
86	        let mut configs = Vec::new();
87	        if dir.exists() {
88	            for entry in std::fs::read_dir(dir)? {
89	                let entry = entry?;
90	                let path = entry.path();
91	                if path.extension().is_some_and(|e| e == "toml") {
92	                    let content = std::fs::read_to_string(&path)?;
93	                    let config: FilterConfig = toml::from_str(&content)?;
94	                    configs.push(config);
95	                }
96	            }
97	        }
98	        Ok(Self { configs })
99	    }
100	
101	    pub fn add_config(&mut self, config: FilterConfig) {
102	        self.configs.push(config);
103	    }
104	
105	    pub fn find_filter(&self, command: &str, args: &[String]) -> Option<&FilterConfig> {
106	        self.configs.iter().find(|c| {
107	            if c.command.name != command {
108	                return false;
109	            }
110	            c.command.args_contain.iter().all(|required| {
111	                args.iter().any(|a| a.contains(required.as_str()))
112	            })
113	        })
114	    }
115	
116	    pub fn apply(&self, command: &str, args: &[String], output: &str) -> FilterResult {
117	        let config = match self.find_filter(command, args) {
118	            Some(c) => c,
119	            None => return FilterResult::passthrough(output),
120	        };
121	        apply_filter(config, output)
122	    }
123	}
