125	#[derive(Debug)]
126	pub struct FilterResult {
127	    pub output: String,
128	    pub input_len: usize,
129	    pub output_len: usize,
130	    pub filter_applied: bool,
131	}
132	
133	impl FilterResult {
134	    fn passthrough(output: &str) -> Self {
135	        let len = output.len();
136	        Self {
137	            output: output.to_string(),
138	            input_len: len,
139	            output_len: len,
140	            filter_applied: false,
141	        }
142	    }
143	}
144	
145	pub fn apply_filter(config: &FilterConfig, output: &str) -> FilterResult {
146	    let input_len = output.len();
147	    let mut text = output.to_string();
148	
149	    // Stage 1: strip_ansi
150	    if config.strip_ansi.unwrap_or(true) {
151	        text = stage_strip_ansi(&text);
152	    }
153	
154	    // Stage 2: replace
155	    for rule in &config.replace {
156	        text = stage_replace(&text, rule);
157	    }
158	
159	    // Stage 3: match_output
160	    if let Some(rule) = &config.match_output {
161	        text = stage_match_output(&text, rule);
162	    }
163	
164	    // Stage 4: strip_lines
165	    for rule in &config.strip_lines {
166	        text = stage_strip_lines(&text, rule);
167	    }
168	
169	    // Stage 5: truncate_lines
170	    if let Some(rule) = &config.truncate_lines {
171	        text = stage_truncate_lines(&text, rule);
172	    }
173	
174	    // Stage 6: head_tail
175	    if let Some(rule) = &config.head_tail {
176	        text = stage_head_tail(&text, rule);
177	    }
178	
179	    // Stage 7: max_lines
180	    if let Some(max) = config.max_lines {
181	        text = stage_max_lines(&text, max);
182	    }
183	
184	    // Stage 8: on_empty
185	    if let Some(fallback) = &config.on_empty {
186	        if text.trim().is_empty() {
187	            text = fallback.clone();
188	        }
189	    }
190	
191	    let output_len = text.len();
192	    FilterResult {
193	        output: text,
194	        input_len,
195	        output_len,
196	        filter_applied: true,
197	    }
198	}
199	
200	fn stage_strip_ansi(text: &str) -> String {
201	    match strip_ansi_escapes::strip_str(text) {
202	        s if s.is_empty() && !text.is_empty() => text.to_string(),
203	        s => s.to_string(),
204	    }
205	}
206	
207	fn stage_replace(text: &str, rule: &ReplaceRule) -> String {
208	    match Regex::new(&rule.pattern) {
209	        Ok(re) => re.replace_all(text, rule.replacement.as_str()).to_string(),
210	        Err(_) => text.to_string(),
211	    }
212	}
213	
214	fn stage_match_output(text: &str, rule: &MatchOutputRule) -> String {
215	    let re = match Regex::new(&rule.pattern) {
216	        Ok(r) => r,
217	        Err(_) => return text.to_string(),
218	    };
219	    let lines: Vec<&str> = text.lines().collect();
220	    let filtered: Vec<&str> = lines
221	        .into_iter()
222	        .filter(|line| {
223	            let matches = re.is_match(line);
224	            if rule.invert { !matches } else { matches }
225	        })
226	        .collect();
227	    filtered.join("\n")
228	}
