230	fn stage_strip_lines(text: &str, rule: &StripLinesRule) -> String {
231	    let re = match Regex::new(&rule.pattern) {
232	        Ok(r) => r,
233	        Err(_) => return text.to_string(),
234	    };
235	    text.lines()
236	        .filter(|line| !re.is_match(line))
237	        .collect::<Vec<_>>()
238	        .join("\n")
239	}
240	
241	fn stage_truncate_lines(text: &str, rule: &TruncateLinesRule) -> String {
242	    text.lines()
243	        .map(|line| {
244	            if line.len() > rule.max_length {
245	                let truncated: String = line.chars().take(rule.max_length).collect();
246	                format!("{}{}", truncated, rule.suffix)
247	            } else {
248	                line.to_string()
249	            }
250	        })
251	        .collect::<Vec<_>>()
252	        .join("\n")
253	}
254	
255	fn stage_head_tail(text: &str, rule: &HeadTailRule) -> String {
256	    let lines: Vec<&str> = text.lines().collect();
257	    let total = lines.len();
258	    if total <= rule.head + rule.tail {
259	        return text.to_string();
260	    }
261	    let head_part: Vec<&str> = lines[..rule.head].to_vec();
262	    let tail_part: Vec<&str> = lines[total - rule.tail..].to_vec();
263	    let omitted = total - rule.head - rule.tail;
264	    let sep = rule.separator.replace("{omitted}", &omitted.to_string());
265	    format!("{}{}{}", head_part.join("\n"), sep, tail_part.join("\n"))
266	}
267	
268	fn stage_max_lines(text: &str, max: usize) -> String {
269	    let lines: Vec<&str> = text.lines().collect();
270	    if lines.len() <= max {
271	        return text.to_string();
272	    }
273	    lines[..max].join("\n")
274	}
