#[cfg(test)]
mod tests {
    use codeflow_core::dedup::DedupCache;
    use codeflow_core::filter::{
        CommandMatch, FilterConfig, FilterPipeline, StripLinesRule,
    };
    use tempfile::TempDir;

    fn make_pipeline_with_strip(command: &str, strip_pattern: &str) -> FilterPipeline {
        let mut pipeline = FilterPipeline::new();
        pipeline.add_config(FilterConfig {
            command: CommandMatch {
                name: command.to_string(),
                args_contain: vec![],
            },
            strip_ansi: Some(false),
            replace: vec![],
            match_output: None,
            strip_lines: vec![StripLinesRule {
                pattern: strip_pattern.to_string(),
            }],
            truncate_lines: None,
            head_tail: None,
            max_lines: None,
            on_empty: None,
        });
        pipeline
    }

    // --- filter-only path ---

    #[test]
    fn test_filter_reduces_output() {
        // Pipeline strips "Downloading" lines — noisy cargo-like output should shrink
        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
        let raw = "Downloading foo v1.0\nDownloading bar v2.0\nCompiling mylib v0.1\nFinished in 3.2s";
        let result = pipeline.apply("cargo", &[], raw);
        assert!(result.filter_applied);
        assert!(
            result.output_len < result.input_len,
            "filtered output ({}) should be smaller than input ({})",
            result.output_len,
            result.input_len
        );
        assert!(!result.output.contains("Downloading"));
        assert!(result.output.contains("Compiling"));
    }

    #[test]
    fn test_filter_passthrough_when_no_match() {
        // Pipeline exists for "cargo" but we apply it to "npm" — passthrough
        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
        let raw = "some output that would normally be filtered";
        let result = pipeline.apply("npm", &[], raw);
        assert!(!result.filter_applied);
        assert_eq!(result.output, raw);
    }

    // --- fail-open: empty pipeline passes through ---

    #[test]
    fn test_empty_pipeline_passthrough() {
        // When filter config is missing/broken, FilterPipeline::new() is used
        // which is exactly what compress() falls back to on error.
        let pipeline = FilterPipeline::new();
        let raw = "important output that must not be lost";
        let result = pipeline.apply("anything", &[], raw);
        assert!(!result.filter_applied, "empty pipeline should not filter");
        assert_eq!(result.output, raw, "output should be unchanged");
        assert_eq!(result.input_len, result.output_len);
    }

    // --- dedup cache within compress pipeline ---

    #[test]
    fn test_dedup_cache_miss_on_first_lookup() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");
        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();

        let result = cache.lookup("cmd:cargo:build", 0, "build output content").unwrap();
        assert!(!result.cache_hit);
        assert_eq!(result.tokens_saved, 0);
    }

    #[test]
    fn test_dedup_cache_hit_on_second_lookup_same_session() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");
        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();

        let content = "build finished successfully\nerror count: 0";
        // First lookup: miss, stores entry
        let r1 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
        assert!(!r1.cache_hit);

        // Second lookup with same mtime=0 and same content: hit
        let r2 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
        assert!(r2.cache_hit);
        assert!(r2.tokens_saved > 0);
        assert!(r2.summary.is_some());
    }

    #[test]
    fn test_dedup_cache_different_sessions_no_hit() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");

        let cache1 = DedupCache::open(&db_path, "session-a").unwrap();
        cache1.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
        drop(cache1);

        // New session — same content, same mtime, but different session_id → miss
        let cache2 = DedupCache::open(&db_path, "session-b").unwrap();
        let r = cache2.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
        assert!(!r.cache_hit, "cross-session lookup must not hit");
    }
}
